const SAT='https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/';
function sat(lat,lon,z,label,note){const n=2**z,xt=(lon+180)/360*n,la=lat*Math.PI/180,yt=(1-Math.log(Math.tan(la)+1/Math.cos(la))/Math.PI)/2*n;
 const x0=Math.floor(xt)-2,y0=Math.floor(yt)-1,px=(xt-x0)*256,py=(yt-y0)*256;let t='';
 for(let j=0;j<3;j++)for(let i=0;i<5;i++)t+=`<img src="${SAT}${z}/${y0+j}/${x0+i}" style="left:${i*256}px;top:${j*256}px" alt="" loading="lazy" referrerpolicy="no-referrer">`;
 const ar=A.LANG==='ar';
 return `<figure class="sat"><div class="sat-in" style="left:calc(50% - ${px.toFixed(0)}px);top:calc(50% - ${py.toFixed(0)}px)">${t}</div><i class="sat-pin"></i><figcaption><b>📍 ${label}</b><span>${note}</span><a href="https://www.google.com/maps/@${lat},${lon},${z+1}z/data=!3m1!1e3" target="_blank" rel="noopener">${ar?'افتح في خرائط Google ←':'Open in Google Maps →'}</a></figcaption><small class="sat-cr">${ar?'صورة قمر صناعي':'Satellite image'} · Esri, Maxar, Earthstar Geographics</small></figure>`;}
A.PHOTOS=PH;A.photoCredits=()=>Object.keys(PH).map(k=>`<li><a href="${CM(k)}" target="_blank" rel="noopener">${cap(k)}</a> — ${PH[k][2]}</li>`).join('');
function saudiMap(app){const host=app.querySelector('.ksa-map');if(!host||host.dataset.live||!A.loadML)return;const ar=A.LANG==='ar';
 const box=document.createElement('div');box.className='ksa-live';box.innerHTML=`<div class="ksa-gl" id="ksaGL"></div><div class="ksa-tg"><button type="button" class="on" data-s="sat">${ar?'قمر صناعي':'Satellite'}</button><button type="button" data-s="map">${ar?'خريطة':'Map'}</button></div>`;
 const pins=[[46.6440,24.7168,ar?'كاكست · المفاعل البحثي':'KACST · research reactor','#22d3ee',16],[39.2485,21.4934,ar?'جامعة الملك عبدالعزيز':'King Abdulaziz University','#a3e635',15.5],[51.2501,24.2501,ar?'خور دويهين (تقريبي)':'Khor Duwaiheen (approx.)','#f472b6',12]];
 A.loadML().then(()=>{if(!document.body.contains(host))return;const ml=window.maplibregl;host.dataset.live=1;host.replaceWith(box);
  const SATS={version:8,sources:{s:{type:'raster',tiles:[SAT+'{z}/{y}/{x}'],tileSize:256,maxzoom:18,attribution:'Esri, Maxar, Earthstar Geographics'}},layers:[{id:'s',type:'raster',source:'s'}]};
  let map;try{map=new ml.Map({container:'ksaGL',style:SATS,center:[45.2,23.9],zoom:4.3,attributionControl:{compact:true},cooperativeGestures:true});}catch(e){box.replaceWith(host);return;}
  map.addControl(new ml.NavigationControl({showCompass:false}),'top-left');
  pins.forEach(([lo,la,l,c,z])=>{const e=document.createElement('div');e.className='ksa-pin';e.style.setProperty('--c',c);e.innerHTML=`<b>${l}</b><i></i>`;e.onclick=ev=>{ev.stopPropagation();map.flyTo({center:[lo,la],zoom:z,speed:1.2});};new ml.Marker({element:e,anchor:'bottom',offset:[0,6]}).setLngLat([lo,la]).addTo(map);});
  box.querySelectorAll('.ksa-tg button').forEach(b=>b.onclick=()=>{box.querySelectorAll('.ksa-tg button').forEach(x=>x.classList.toggle('on',x===b));map.setStyle(b.dataset.s==='sat'?SATS:'https://tiles.openfreemap.org/styles/liberty');});
  map.on('load',()=>{try{map.fitBounds([[38.9,20.9],[51.9,25.4]],{padding:{top:70,bottom:40,left:60,right:60},duration:0});}catch(e){}});A._ksaMap=map;}).catch(()=>{});}

