function decorate(v){const app=document.getElementById('app');if(!app)return;const ar=A.LANG==='ar';
 if(v==='home'){const h=app.querySelector('header.hero');if(h&&!h.querySelector('.hero-sky')){h.insertAdjacentHTML('afterbegin',IMG('cool',1280,'hero-photo',true,'header.hero'));h.insertAdjacentHTML('beforeend',HOME_ART+cred('cool'));}}
 else{const sh=app.querySelector('.sh');if(sh&&!sh.classList.contains('pg-hero')){sh.classList.add('pg-hero');const nav=(A.C&&A.C.nav)||{};
  sh.insertAdjacentHTML('afterbegin',`<div class="crumb"><a href="#home">${nav.home||'Home'}</a><span>›</span><b>${nav[v]||''}</b></div>`);
  sh.insertAdjacentHTML('beforeend',`<div class="pg-art">${ART[v]||ART.atoms}</div>`);
  const k=PAGE_PH[v];if(k){sh.insertAdjacentHTML('afterbegin',IMG(k,1280,'pg-photo',true,'.sh'));sh.insertAdjacentHTML('beforeend',cred(k));}}}
 if(v==='radiation')app.querySelectorAll('.card>.ic').forEach(ic=>{const k=ic.textContent.trim();if(RADIC[k]&&!ic.dataset.p){ic.dataset.p=1;ic.classList.add('ic-rad');ic.innerHTML=RADIC[k];}});
 ORGRULES.filter(r=>r[0]===v).forEach(([,rx,k,na,ne])=>{const h=[...app.querySelectorAll('.card h3,.card h4')].find(x=>rx.test(x.textContent.trim()));if(!h)return;const card=h.closest('.card');if(!card||card.querySelector(':scope>figure.cph'))return;card.classList.add('has-ph');
  card.insertAdjacentHTML('afterbegin',`<figure class="cph org-art">${ORGART[k].replace(/oag/g,"oag"+k).replace(/ckg/g,"ckg"+k)}<figcaption><span>${ar?na:ne}</span><small>${ar?'رسم توضيحي من NE for All':'Illustration by NE for All'}</small></figcaption></figure>`);});
 // photos inside the exact cards they illustrate
 RULES.filter(r=>r[0]===v).forEach(([,rx,k])=>{const hs=[...app.querySelectorAll('.card h3,.card h4,.panel.rinfo h3,.panel h3')];const h=hs.find(x=>rx.test(x.textContent.trim().replace(/\s+/g,' ')));if(!h)return;
  const card=h.closest('.card,.panel');if(!card||card.querySelector(':scope>figure.cph'))return;card.classList.add('has-ph');card.insertAdjacentHTML('afterbegin',FIG(k));});
 if(v==='stories')app.querySelectorAll('.story-head').forEach(sh=>{const t=sh.textContent;const m=STORY.find(([rx])=>rx.test(t));if(!m||sh.nextElementSibling&&sh.nextElementSibling.classList.contains('sph'))return;sh.insertAdjacentHTML('afterend',FIG(m[1],'cph sph'));});
 if(v==='saudi'){
  app.querySelectorAll('.card').forEach(c=>{const h=c.querySelector('h3');if(!h)return;const t=h.textContent;const ill=c.querySelector('.ill');if(!ill)return;
   if(/LPRR/.test(t))ill.outerHTML=`<figure class="sat ph-real"><img src="https://www.iaea.org/sites/default/files/styles/landing_desktop_1920x480/public/2025-01/opal2-banner.jpg.webp?itok=-nzdoBam" alt="" fetchpriority="high" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='https://www.iaea.org/sites/default/files/2025-01/opal2-banner.jpg'"><figcaption><b>${ar?'حوض قلب مفاعل أبحاث من تصميم INVAP':'Pool of an INVAP-designed research reactor'}</b><span>${ar?'مفاعل OPAL الأسترالي، من الشركة الأرجنتينية نفسها اللي صمّمت مفاعل LPRR (صورة توضيحية)':'OPAL, Australia — same designer (INVAP) as the LPRR (illustrative)'}</span></figcaption><small class="sat-cr">${ar?'الصورة':'Photo'}: IAEA</small></figure>`;
   else if(/دويهين|Duwaiheen/.test(t))ill.outerHTML=`<figure class="sat ph-real"><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/Kernkraftwerk_Grafenrheinfeld_-_2013.jpg/960px-Kernkraftwerk_Grafenrheinfeld_-_2013.jpg" alt="" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='https://commons.wikimedia.org/wiki/Special:FilePath/Kernkraftwerk_Grafenrheinfeld_-_2013.jpg?width=960'"><figcaption><b>${ar?'محطة طاقة نووية كبيرة بمفاعل ماء مضغوط':'A large pressurized-water nuclear plant'}</b><span>${ar?'صورة توضيحية لمحطة غرافنراينفيلد في ألمانيا؛ محطة خور دويهين ما بُنيت بعد':'Illustrative: Grafenrheinfeld, Germany — Khor Duwaiheen is not built yet'}</span></figcaption><small class="sat-cr">Avda · CC BY-SA 3.0</small></figure>`;});
  saudiMap(app);}
 if(A.cleanEmoji){A.cleanEmoji(app);A.cleanEmoji(document.getElementById('side'));A.cleanEmoji(document.querySelector('nav'));}}
